source.sqlReaderQuery:
select top 20 o.order_id, c.customer_id, o.order_date, concat(c.first_name, ' ', c.last_name) as full_name, o.total_amount
from orders o
inner join customers c on c.customer_id = o.customer_id;

scripts.text:
select distinct state 
from customers
where state in ('LA', 'NC', 'WA', 'AK', 'GA', 'HI');
